# ---------------------------------------------------------------------------
# Framebuffer -- supersampled rendering (SS=2)
#
# All drawing happens in a 2048x2048 device buffer (DBUF) at twice the
# output resolution; write_png box-averages each 2x2 device block down to
# one output pixel.  That is deterministic, standard-library-only
# anti-aliasing: thin strokes get smooth grey edge pixels instead of
# jagged 1 px stair-steps.  Coordinates in the drawing code stay in the
# logical 1024x1024 space; the primitives scale by SS internally.
# Setting SS=1 reproduces the exact 1x render (no-op downsample).
# ---------------------------------------------------------------------------
SS = 2
DW, DH = W * SS, H * SS
DBUF = bytearray(DW * DH * 3)
BUF = bytearray(W * H * 3)


def _fill_paper():
    r, g, b = PAPER
    for i in range(0, len(DBUF), 3):
        DBUF[i] = r
        DBUF[i + 1] = g
        DBUF[i + 2] = b


def set_pixel(x, y, color):
    """Device coordinates (already scaled by the caller)."""
    x = int(x)
    y = int(y)
    if 0 <= x < DW and 0 <= y < DH:
        i = (y * DW + x) * 3
        DBUF[i] = color[0]
        DBUF[i + 1] = color[1]
        DBUF[i + 2] = color[2]


def fill_rect(x, y, w, h, color):
    """Logical coordinates; scaled by SS into the device buffer."""
    x0 = max(0, int(x * SS))
    y0 = max(0, int(y * SS))
    x1 = min(DW, int((x + w) * SS))
    y1 = min(DH, int((y + h) * SS))
    if x1 <= x0 or y1 <= y0:
        return
    r, g, b = color
    for yy in range(y0, y1):
        base = (yy * DW + x0) * 3
        for xx in range(x0, x1):
            i = base + (xx - x0) * 3
            DBUF[i] = r
            DBUF[i + 1] = g
            DBUF[i + 2] = b


def vgrad_rect(x, y, w, h, c_top, c_bot):
    """Vertical linear gradient rectangle (logical coordinates)."""
    x0 = max(0, int(x * SS))
    y0 = max(0, int(y * SS))
    x1 = min(DW, int((x + w) * SS))
    y1 = min(DH, int((y + h) * SS))
    if x1 <= x0 or y1 <= y0:
        return
    span = max(1, y1 - y0 - 1)
    for yy in range(y0, y1):
        t = (yy - y0) / span
        r = int(c_top[0] + (c_bot[0] - c_top[0]) * t)
        g = int(c_top[1] + (c_bot[1] - c_top[1]) * t)
        b = int(c_top[2] + (c_bot[2] - c_top[2]) * t)
        base = (yy * DW + x0) * 3
        for xx in range(x0, x1):
            i = base + (xx - x0) * 3
            DBUF[i] = r
            DBUF[i + 1] = g
            DBUF[i + 2] = b


# --- discs (cached offset masks) -------------------------------------------
_DISC_CACHE = {}


def _disc_offsets(radius):
    key = round(radius, 2)
    if key not in _DISC_CACHE:
        ri = int(math.ceil(radius))
        offs = []
        for dy in range(-ri, ri + 1):
            for dx in range(-ri, ri + 1):
                if dx * dx + dy * dy <= radius * radius + 0.5:
                    offs.append((dx, dy))
        _DISC_CACHE[key] = offs
    return _DISC_CACHE[key]


def disc(cx, cy, radius, color):
    """Disc; logical centre/radius, scaled into the device buffer."""
    for ox, oy in _disc_offsets(radius * SS):
        set_pixel(cx * SS + ox, cy * SS + oy, color)


def draw_line(x0, y0, x1, y1, color, weight=1):
    """Thick line: stamp discs along the segment.
    Logical coordinates/weight; scaled by SS into the device buffer."""
    x0, y0, x1, y1 = x0 * SS, y0 * SS, x1 * SS, y1 * SS
    w = weight * SS
    dx = x1 - x0
    dy = y1 - y0
    length = math.hypot(dx, dy)
    if length < 0.001:
        for ox, oy in _disc_offsets(w / 2.0):
            set_pixel(x0 + ox, y0 + oy, color)
        return
    steps = max(1, int(length / max(1.0, w / 3.0)))
    offs = _disc_offsets(w / 2.0)
    for i in range(steps + 1):
        t = i / steps
        cx = int(round(x0 + dx * t))
        cy = int(round(y0 + dy * t))
        for ox, oy in offs:
            set_pixel(cx + ox, cy + oy, color)


def polyline(points, color, weight=1, closed=False):
    pts = list(points)
    if closed and len(pts) > 2:
        pts = pts + [pts[0]]
    for i in range(len(pts) - 1):
        draw_line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1],
                  color, weight)


def fill_poly(points, color):
    """Even-odd scanline polygon fill.  Logical points; scaled by SS."""
    if len(points) < 3:
        return
    pts = [(px * SS, py * SS) for px, py in points]
    ys = [p[1] for p in pts]
    y0 = max(0, int(math.floor(min(ys))))
    y1 = min(DH - 1, int(math.ceil(max(ys))))
    n = len(pts)
    for y in range(y0, y1 + 1):
        xs = []
        for i in range(n):
            x0, y0p = pts[i]
            x1, y1p = pts[(i + 1) % n]
            if (y0p <= y < y1p) or (y1p <= y < y0p):
                t = (y - y0p) / (y1p - y0p)
                xs.append(x0 + t * (x1 - x0))
        xs.sort()
        for i in range(0, len(xs) - 1, 2):
            xa = max(0, int(math.ceil(xs[i])))
            xb = min(DW - 1, int(math.floor(xs[i + 1])))
            for x in range(xa, xb + 1):
                set_pixel(x, y, color)


def arc(cx, cy, radius, a0, a1, color, weight=1):
    """Arc of a circle, angles in degrees, 0 = east, clockwise (y down)."""
    span = abs(a1 - a0)
    steps = max(2, int(span * radius / 6.0))
    prev = None
    for i in range(steps + 1):
        a = math.radians(a0 + (a1 - a0) * i / steps)
        px = cx + radius * math.cos(a)
        py = cy + radius * math.sin(a)
        if prev is not None:
            draw_line(prev[0], prev[1], px, py, color, weight)
        prev = (px, py)


def circle_outline(cx, cy, radius, color, weight=1):
    arc(cx, cy, radius, 0, 360, color, weight)


def starburst(cx, cy, r_outer, r_inner, spikes, color):
    """Radial star / explosion shape, filled."""
    pts = []
    for i in range(spikes * 2):
        a = math.pi * i / spikes - math.pi / 2
        r = r_outer if i % 2 == 0 else r_inner
        pts.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    fill_poly(pts, color)


def ring(cx, cy, r_outer, r_inner, color):
    """Filled ring (annulus) via disc subtraction by drawing outer disc
    then inner disc in paper colour is NOT safe on non-paper backgrounds,
    so draw it as a thick circle outline instead."""
    circle_outline(cx, cy, (r_outer + r_inner) / 2.0, color,
                   weight=max(1, int(r_outer - r_inner)))

# ---------------------------------------------------------------------------
# Filled-outline fonts (defined in-code, no external font files)
#
# The v3 font was single-stroke ("technical lettering"): every letter was
# a set of thin lines, so at any size it looked like engineering
# lettering, never like a printed newspaper face.  This rebuild replaces
# it with FILLED outlines: each glyph is a set of closed polygons that
# are filled solid, exactly like a real digital font.  Two faces:
#   * SANS -- a clean geometric-humanist sans (Helvetica-like) for body
#     copy, headlines, labels, index, DATE CHECK, footer and map.  Two
#     weights: Regular (stem 1.0, light book weight for sentences) and
#     Bold (stem 2.0).
#   * SERIF -- a slab serif (Rockwell-like: uniform stems + square slab
#     feet) used ONLY for the huge date line and the masthead, so the
#     front page reads like a real newspaper.  Only the characters that
#     occur in "FRIDAY 20 NOVEMBER 2026" and "THE WORLD IN ONE DAY"
#     are defined.
# Cell: x 0..~7, y 0 (cap top) .. 10 (baseline) .. 13 (descender).
# Glyphs are built from rectangles, ellipses and elliptical ring
# sectors, composed with the non-zero winding rule (see fill_contours):
# outer contours run clockwise, holes counter-clockwise, so overlapping
# same-direction parts both fill and holes stay empty on any background.
# ---------------------------------------------------------------------------

def _shoelace(pts):
    s = 0.0
    n = len(pts)
    for i in range(n):
        x0, y0 = pts[i]
        x1, y1 = pts[(i + 1) % n]
        s += x0 * y1 - x1 * y0
    return s


def _orient(pts, want_positive=True):
    """Force a contour's winding: positive shoelace = clockwise on
    screen (y down).  Outer contours want positive, holes negative,
    so glyph authors never have to track point order by hand."""
    if not pts:
        return pts
    s = _shoelace(pts)
    if (s > 0) != want_positive:
        return pts[::-1]
    return list(pts)


def _rect(x0, y0, x1, y1):
    return _orient([(x0, y0), (x1, y0), (x1, y1), (x0, y1)], True)


def _ell(cx, cy, rx, ry, n=24):
    pts = []
    for i in range(n):
        a = 2.0 * math.pi * i / n
        pts.append((cx + rx * math.cos(a), cy + ry * math.sin(a)))
    return _orient(pts, True)


def _ell_hole(cx, cy, rx, ry, n=18):
    return _orient(_ell(cx, cy, rx, ry, n), False)


def _esector(cx, cy, rxo, ryo, rxi, ryi, a0, a1, n=18):
    """Elliptical ring sector: a thick curved band from angle a0 to a1.
    Angles in degrees, 0=east, 90=south (y down), increasing=clockwise.
    Outer arc a0->a1, then inner arc a1->a0, closed into one contour."""
    pts = []
    for i in range(n + 1):
        a = math.radians(a0 + (a1 - a0) * i / n)
        pts.append((cx + rxo * math.cos(a), cy + ryo * math.sin(a)))
    for i in range(n + 1):
        a = math.radians(a1 - (a1 - a0) * i / n)
        pts.append((cx + rxi * math.cos(a), cy + ryi * math.sin(a)))
    return _orient(pts, True)


def _poly(pts):
    return _orient(list(pts), True)


def _hole_poly(pts):
    return _orient(list(pts), False)


def _diag(x0, y0, x1, y1, t):
    """Parallelogram bar from (x0,y0) to (x1,y1), horizontal thickness t."""
    return _orient([(x0, y0), (x1, y1), (x1 + t, y1), (x0 + t, y0)], True)


def fill_contours(contours, color):
    """Fill a list of polygons with the non-zero winding rule.
    Logical coordinates; scaled by SS into the device buffer.
    A point is painted when the winding number of the edges crossing
    its scanline is non-zero, so overlapping outer contours both fill
    and counter-clockwise holes stay empty on any background."""
    r, g, b = color
    edges = []
    for poly in contours:
        n = len(poly)
        if n < 3:
            continue
        pts = [(px * SS, py * SS) for px, py in poly]
        for i in range(n):
            x0, y0 = pts[i]
            x1, y1 = pts[(i + 1) % n]
            if y0 == y1:
                continue
            edges.append((x0, y0, x1, y1))
    if not edges:
        return
    ymin = min(min(e[1], e[3]) for e in edges)
    ymax = max(max(e[1], e[3]) for e in edges)
    y0 = max(0, int(math.floor(ymin)))
    y1 = min(DH - 1, int(math.ceil(ymax)))
    for y in range(y0, y1 + 1):
        cross = []
        for x0, ey0, x1, ey1 in edges:
            if (ey0 <= y < ey1) or (ey1 <= y < ey0):
                tt = (y - ey0) / (ey1 - ey0)
                cross.append((x0 + tt * (x1 - x0), 1 if ey1 > ey0 else -1))
        cross.sort()
        w = 0
        x_start = None
        for x, d in cross:
            prev = w
            w += d
            if prev == 0 and w != 0:
                x_start = x
            elif prev != 0 and w == 0 and x_start is not None:
                xa = max(0, int(math.ceil(x_start)))
                xb = min(DW - 1, int(math.floor(x)))
                if xb >= xa:
                    base = (y * DW + xa) * 3
                    for xx in range(xa, xb + 1):
                        i = base + (xx - xa) * 3
                        DBUF[i] = r
                        DBUF[i + 1] = g
                        DBUF[i + 2] = b
                x_start = None

# --- sans-serif face -------------------------------------------------------
# build_font(t): glyph dict for stem thickness t.
# Returns {char: (advance, [contours])}.  Regular t=1.3, Bold t=2.0.
# Cell: cap y 0..10, x-height y 3..10, baseline y 10, descender y 13.

# --- Liberation outline fonts (SIL OFL 1.1) -------------------------
