# Tracking: extra advance added between every two glyphs (font units).
# Liberation advances already space letters correctly, so no extra.
TRACK = 0


def _pick_font(font, weight):
    """Select the glyph table: explicit serif (date/masthead), explicit
    sans-reg (small labels/sources), else Bold for weight>=1.35,
    else Regular (Serif Regular body).  Weight only chooses the
    weight class; the outlines themselves are real Liberation glyphs."""
    if font == "serif":
        return _FONT_SERIF
    if font == "serif-it":
        return _FONT_SERIF_IT
    if font == "sans-reg":
        return _FONT_SANS_REG
    return _FONT_BOLD if weight >= 1.35 else _FONT_REG


def text_width(s, size, font="sans", weight=1.2):
    table = _pick_font(font, weight)
    scale = size / 1000.0
    w = 0.0
    for ch in s:
        adv = table.get(ch, _FALLBACK)[0]
        w += (adv + TRACK) * scale
    if s:
        w -= TRACK * scale  # no trailing tracking after the last glyph
    return w


def draw_text(s, x, y, size, color, weight=1.2, align="left", font="sans"):
    """Draw filled text; (x, y) is the top-left of the cap-height box.
    align: left / center / right, relative to x.  Returns drawn width.
    Glyph outlines are filled (not stroked) and scaled by size/10, then
    by SS inside fill_contours, so supersampling anti-aliases them."""
    table = _pick_font(font, weight)
    w = text_width(s, size, font, weight)
    if align == "center":
        x = x - w / 2.0
    elif align == "right":
        x = x - w
    scale = size / 1000.0
    cx = x
    for ch in s:
        adv, contours = table.get(ch, _FALLBACK)
        if contours:
            # contours are FLAT int lists [x0,y0,x1,y1,...] in the
            # 1000-unit cell; scale them into logical coordinates.
            scaled = [[(cx + c[i] * scale, y + c[i + 1] * scale)
                       for i in range(0, len(c), 2)]
                      for c in contours]
            fill_contours(scaled, color)
        cx += (adv + TRACK) * scale
    return w


def fit_size(s, size, max_w, font="sans", weight=1.2):
    """Shrink size until the text fits max_w; returns the size used."""
    while size > 6 and text_width(s, size, font, weight) > max_w:
        size -= 0.5
    return size


def wrap_text(s, size, max_w, font="sans", weight=1.2):
    lines = []
    for para in s.split("\n"):
        words = para.split(" ")
        cur = ""
        for word in words:
            trial = (cur + " " + word).strip()
            if text_width(trial, size, font, weight) <= max_w or not cur:
                cur = trial
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
    return lines


def draw_block(s, x, y, size, color, weight, max_w, lh, align="left",
               font="sans"):
    """Draw wrapped text; returns total height used."""
    lines = wrap_text(s, size, max_w, font, weight)
    for i, ln in enumerate(lines):
        if align == "center":
            draw_text(ln, x + max_w / 2.0, y + i * lh, size, color, weight,
                      align="center", font=font)
        elif align == "right":
            draw_text(ln, x + max_w, y + i * lh, size, color, weight,
                      align="right", font=font)
        else:
            draw_text(ln, x, y + i * lh, size, color, weight, font=font)
    return len(lines) * lh

# ---------------------------------------------------------------------------
# PNG encoder (hand-written: signature, IHDR, IDAT, IEND; CRC32 via zlib)
# ---------------------------------------------------------------------------
def _png_chunk(tag, data):
    out = struct.pack(">I", len(data)) + tag + data
    out += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    return out


def write_png(path):
    # Box-average downsample: each SSxSS device block becomes one
    # output pixel.  Integer math only, so the result is deterministic.
    if SS == 1:
        BUF[:] = DBUF[:]
    else:
        db = DBUF
        dw3 = DW * 3
        for oy in range(H):
            drow = (oy * SS) * dw3
            orow = oy * W * 3
            for ox in range(W):
                i0 = drow + (ox * SS) * 3
                i1 = i0 + 3
                i2 = i0 + dw3
                i3 = i2 + 3
                j = orow + ox * 3
                BUF[j] = (db[i0] + db[i1] + db[i2] + db[i3]) // 4
                BUF[j + 1] = (db[i0 + 1] + db[i1 + 1] + db[i2 + 1]
                              + db[i3 + 1]) // 4
                BUF[j + 2] = (db[i0 + 2] + db[i1 + 2] + db[i2 + 2]
                              + db[i3 + 2]) // 4
    raw = bytearray()
    row_bytes = W * 3
    for yy in range(H):
        raw.append(0)  # filter: None
        raw += BUF[yy * row_bytes:(yy + 1) * row_bytes]
    comp = zlib.compress(bytes(raw), 9)  # deterministic for fixed input
    png = b"\x89PNG\r\n\x1a\n"
    png += _png_chunk(b"IHDR", struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0))
    png += _png_chunk(b"IDAT", comp)
    png += _png_chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)
    return len(png)


# ---------------------------------------------------------------------------
# Typographic hierarchy -- stroke weight in pixels per text category.
# v1 used one heavy weight (2.5-7) for everything, which filled the
# counters of small letters and made body copy read as blobs.  Body copy
# is now a light book weight; display type is larger but still slender,
# so the stroke stays a small fraction of the cap height in every size.
# ---------------------------------------------------------------------------
W_BODY      = 1.2   # story descriptions, ALSO bullets, DATE CHECK body
W_SOURCE    = 1.0   # source labels (small but legible)
W_LABEL     = 1.1   # numbers-strip labels, map legend, footer
W_KICKER    = 1.4   # card kicker tags
W_BADGE     = 1.6   # digits inside the number badges
W_HEAD_MED  = 1.4   # medium-card headlines
W_HEAD_LEAD = 1.6   # lead-card headlines
W_SUBHEAD   = 1.4   # subhead under the date
W_TOPSTRIP  = 1.3   # top strip / edition line
W_MASTHEAD  = 1.8   # "THE WORLD IN ONE DAY"
W_DATE      = 2.2   # the huge date line (large, but slender, not 7)
W_NUM       = 2.2   # big numbers in the key-numbers strip
W_MAPTITLE  = 1.4   # "WHERE IT HAPPENED" / "ALSO ON..." / "DATE CHECK"


# ---------------------------------------------------------------------------
# Layout constants
# ---------------------------------------------------------------------------
MX = 36            # left / right margin
CW = W - 2 * MX    # content width = 952


def hline(x, y, w, color, weight=1):
    fill_rect(x, y, w, weight, color)


def vline(x, y, h, color, weight=1):
    fill_rect(x, y, weight, h, color)


def number_badge(cx, cy, r, num, bg=AMBER, fg=INK, size=13, weight=W_BADGE):
    disc(cx, cy, r, bg)
    circle_outline(cx, cy, r, fg, weight=1)
    draw_text(str(num), cx, cy - size / 2.0, size, fg, weight, align="center")
def ill_kyiv(x, y, w, h):
    """Night strike on three Dnipro bridges: sky, skyline, river, arches,
    two explosions."""
    vgrad_rect(x, y, w, h, SKY_NIGHT, SKY_NIGHT2)
    # stars (fixed positions -- deterministic)
    for sx, sy in [(0.08, 0.12), (0.22, 0.07), (0.38, 0.16), (0.55, 0.08),
                   (0.68, 0.14), (0.82, 0.06), (0.94, 0.18), (0.47, 0.22)]:
        disc(x + sx * w, y + sy * h, 1.2, (200, 205, 220))
    # moon
    disc(x + 0.88 * w, y + 0.16 * h, 9, (240, 236, 210))
    disc(x + 0.88 * w + 3, y + 0.16 * h - 2, 7, SKY_NIGHT)
    # skyline silhouettes
    base = y + h - 20
    sky = (42, 58, 96)
    for bx, bw, bh in [(0.00, 0.10, 26), (0.11, 0.07, 38), (0.19, 0.09, 20),
                       (0.29, 0.06, 32), (0.36, 0.10, 22), (0.47, 0.08, 40),
                       (0.56, 0.07, 24), (0.64, 0.09, 34), (0.74, 0.06, 20),
                       (0.81, 0.08, 30), (0.90, 0.10, 22)]:
        fill_rect(x + bx * w, base - bh, bw * w, bh, sky)
    # river
    fill_rect(x, base, w, 20, RIVER)
    for rx in range(0, int(w), 26):
        hline(x + rx + 6, base + 7, 14, (170, 200, 230), 1)
        hline(x + rx + 12, base + 14, 10, (150, 185, 220), 1)
    # three bridges: deck + arch + posts
    for bx0, bx1 in [(0.10, 0.36), (0.42, 0.64), (0.70, 0.94)]:
        ax0, ax1 = x + bx0 * w, x + bx1 * w
        deck_y = base - 6
        draw_line(ax0, deck_y, ax1, deck_y, (200, 205, 220), 2)
        arc((ax0 + ax1) / 2.0, deck_y + 2, (ax1 - ax0) / 2.0, 180, 360,
            (200, 205, 220), 2)
        draw_line(ax0, deck_y, ax0, base, (200, 205, 220), 2)
        draw_line(ax1, deck_y, ax1, base, (200, 205, 220), 2)
    # explosions over bridge 1 and bridge 3
    for ex, ey in [(0.23, 0.42), (0.82, 0.40)]:
        ex, ey = x + ex * w, y + ey * h
        disc(ex, ey, 20, (242, 142, 42))
        starburst(ex, ey, 17, 8, 8, AMBER)
        starburst(ex, ey, 9, 4, 8, (255, 226, 140))
        disc(ex - 12, ey - 16, 7, (140, 140, 152))
        disc(ex + 10, ey - 20, 5, (162, 162, 172))
    # searchlight beams
    draw_line(x + 0.05 * w, y + h, x + 0.30 * w, y + 0.10 * h,
              (170, 190, 222), 1)
    draw_line(x + 0.95 * w, y + h, x + 0.72 * w, y + 0.12 * h,
              (170, 190, 222), 1)


def ill_akvan(x, y, w, h):
    """Cyclone spiral over the Odisha coast."""
    vgrad_rect(x, y, w, h, (210, 230, 240), (185, 215, 232))
    # land (east coast of India) on the right
    land = [(x + 0.62 * w, y), (x + w, y), (x + w, y + h),
            (x + 0.72 * w, y + h), (x + 0.66 * w, y + 0.62 * h),
            (x + 0.70 * w, y + 0.34 * h), (x + 0.58 * w, y + 0.12 * h)]
    fill_poly(land, (222, 205, 170))
    polyline(land, (120, 105, 80), 2)
    # spiral bands
    cx, cy = x + 0.44 * w, y + 0.52 * h
    for r, a0, a1 in [(14, -40, 300), (26, 60, 400), (38, 140, 480),
                      (50, 220, 560)]:
        arc(cx, cy, r, a0, a1, (30, 150, 140), 4)
    disc(cx, cy, 6, INK)
    # rain streaks
    for rx, ry in [(0.08, 0.15), (0.16, 0.35), (0.06, 0.55), (0.14, 0.72),
                   (0.24, 0.20), (0.30, 0.55), (0.10, 0.85), (0.22, 0.88)]:
        draw_line(x + rx * w, y + ry * h, x + rx * w - 5, y + ry * h + 12,
                  WHITE, 1)
    # wind arrows around the spiral
    for ax, ay, ang in [(0.44, 0.18, 100), (0.72, 0.52, 190), (0.44, 0.86, 280)]:
        ax, ay = x + ax * w, y + ay * h
        dx, dy = math.cos(math.radians(ang)), math.sin(math.radians(ang))
        draw_line(ax, ay, ax + dx * 16, ay + dy * 16, INK, 2)
        draw_line(ax + dx * 16, ay + dy * 16,
                  ax + dx * 10 - dy * 5, ay + dy * 10 + dx * 5, INK, 2)
        draw_line(ax + dx * 16, ay + dy * 16,
                  ax + dx * 10 + dy * 5, ay + dy * 10 - dx * 5, INK, 2)


