# ---------------------------------------------------------------------------
# Page sections (40-story layout)
# ---------------------------------------------------------------------------
# Vertical budget (1024 tall):
#   top line 12 | date 38 | subhead 106 | rules 128/133 | numbers 140-206
#   lead 214-414 | medium 422-582 | small 590-734
#   bottom band 742-986 | footer 992
# NOTE: the embedded Liberation tables lack U+2019/U+2018 (curly quotes),
# U+2212 (minus), U+00D7 and U+2265 -- those render as "?". Use ASCII
# apostrophe (') and hyphen (-) instead. U+2013/U+2014 (dashes), U+00A3
# (pound), U+20AC (euro), U+00B7 and U+2022 ARE present.
LEAD_Y, LEAD_H = 234, 200
LEAD_W = 309
MED_Y, MED_H = 442, 158
MED_W = 182
