# Key numbers strip: Mana's six numbers, black on cream, red separators.
# Reproduced exactly as printed on his page.
STRIP = [
    ("40", "major stories from around the world"),
    ("8", "regions covered across the globe"),
    ("300,000+", "people evacuated before cyclone landfall"),
    ("5.1%", "Asian markets fall amid AI fears"),
    ("\u00a35.1bn", "UK-EU deal value per year by 2040"),
    ("118", "countries get influenza vaccine"),
]


def draw_numbers_strip(y=138, h=62):
    fill_rect(MX, y, CW, h, PAPER)
    cell_w = CW / 6.0
    for i, (num, label) in enumerate(STRIP):
        cx = MX + i * cell_w
        if i:
            vline(cx, y + 6, h - 12, RED, weight=1)
        nsize = fit_size(num, 26, cell_w - 14, font="sans", weight=W_NUM)
        draw_text(num, cx + cell_w / 2.0, y + 4, nsize, BLACK, W_NUM,
                  align="center", font="sans")
        draw_block(label, cx + 8, y + 34, 9.5, BLACK, W_LABEL,
                   cell_w - 16, 12, font="sans-reg")


