def lead_card(x, header, headline, deck, tag, source, ill):
    y = LEAD_Y
    card_frame(x, y, LEAD_W, LEAD_H)
    fill_rect(x + 1, y + 1, LEAD_W - 2, 24, RED)
    draw_text(header, x + 10, y + 5, 13, WHITE, W_KICKER, font="sans")
    tx = x + 10
    tw = 168
    hh = draw_block(headline, tx, y + 32, 15, INK, W_HEAD_LEAD, tw, 19,
                    font="serif")
    draw_block(deck, tx, y + 32 + hh + 4, 10.5, INK_SOFT, W_BODY, tw, 13,
               font="serif-reg")
    tag_w = text_width(tag, 9, "sans", W_KICKER) + 10
    fill_rect(tx, y + LEAD_H - 20, tag_w, 15, RED)
    draw_text(tag, tx + 5, y + LEAD_H - 18, 9, WHITE, W_KICKER, font="sans")
    draw_text("Source: " + source, tx + tag_w + 6, y + LEAD_H - 18, 8,
              GRAY, W_SOURCE, font="sans-reg")
    ill(x + 182, y + 25, LEAD_W - 183, LEAD_H - 26)


def medium_card(x, header, headline, deck, footer, ill, accent):
    y = MED_Y
    card_frame(x, y, MED_W, MED_H)
    fill_rect(x + 1, y + 1, MED_W - 2, 20, accent)
    draw_text(header, x + 8, y + 4, 11, WHITE, W_KICKER, font="sans")
    ill(x + 1, y + 21, MED_W - 2, 54)
    hh = draw_block(headline, x + 8, y + 80, 12, INK, W_HEAD_MED,
                    MED_W - 16, 15.5, font="serif")
    draw_block(deck, x + 8, y + 80 + hh + 3, 9.5, INK_SOFT, W_BODY,
               MED_W - 16, 13.5, font="serif-reg")
    draw_text(footer, x + MED_W - 8, y + MED_H - 13, 8.5, GRAY, W_SOURCE,
              align="right", font="sans-reg")


def small_card(x, header, headline, deck, footer, ill, accent):
    y = SMALL_Y
    card_frame(x, y, SMALL_W, SMALL_H)
    fill_rect(x + 1, y + 1, SMALL_W - 2, 20, accent)
    draw_text(header, x + 8, y + 4, 11, WHITE, W_KICKER, font="sans")
    ill(x + 1, y + 21, 62, SMALL_H - 22)
    tx = x + 70
    tw = SMALL_W - 78
    hh = draw_block(headline, tx, y + 26, 11.5, INK, W_HEAD_MED, tw, 15,
                    font="serif")
    draw_block(deck, tx, y + 26 + hh + 3, 9.5, INK_SOFT, W_BODY, tw, 13,
               font="serif-reg")
    draw_text(footer, x + SMALL_W - 8, y + SMALL_H - 12, 8.5, GRAY,
              W_SOURCE, align="right", font="sans-reg")


