def droplet_pin(cx, cy, r, color):
    """A map-marker droplet: round head, pointed foot, white centre dot."""
    disc(cx, cy - 0.35 * r, r, color)
    fill_poly([(cx - 0.82 * r, cy - 0.05 * r), (cx + 0.82 * r, cy - 0.05 * r),
               (cx, cy + 1.05 * r)], color)
    disc(cx, cy - 0.35 * r, 0.38 * r, WHITE)


def check_mark(cx, cy, s, color):
    """A hand-drawn tick (the font has no U+2713)."""
    draw_line(cx, cy + 0.35 * s, cx + 0.35 * s, cy + 0.75 * s, color, 2)
    draw_line(cx + 0.35 * s, cy + 0.75 * s, cx + s, cy, color, 2)


def draw_map_panel(x, y, w, h):
    fill_rect(x, y, w, 22, MAP_DARK)
    draw_text("WHERE IT HAPPENED", x + 8, y + 5, 11, WHITE, W_MAPTITLE,
              font="sans")
    mx, my, mw, mh = x + 2, y + 24, w - 4, h - 26
    fill_rect(mx, my, mw, mh, MAP_DARK)

    def proj(lon, lat):
        px = mx + (lon + 170.0) / 360.0 * mw
        py = my + (75.0 - lat) / 130.0 * mh
        return (px, py)

    for poly in (_NA, _GREENLAND, _SA, _AFRICA, _EURASIA, _AUSTRALIA):
        pts = [proj(lon, lat) for lon, lat in poly]
        fill_poly(pts, LAND)
        polyline(pts, INK, 1, closed=True)
    for lon, lat, color in PINS:
        px, py = proj(lon, lat)
        droplet_pin(px, py, 7, color)


def draw_index_panel(x, y, w, h):
    fill_rect(x, y, w, 22, MAP_DARK)
    _t = "ALSO ON FRIDAY 20 NOVEMBER \u2014 27 MORE STORIES"
    _ts = fit_size(_t, 10.5, w - 16, font="sans", weight=W_MAPTITLE)
    draw_text(_t, x + 8, y + 5, _ts, WHITE, W_MAPTITLE, font="sans")
    col_w = (w - 12) // 2
    for col_i in range(2):
        items = INDEX_ITEMS[col_i * 14:(col_i + 1) * 14] \
            if col_i == 0 else INDEX_ITEMS[14:]
        cx = x + col_i * (col_w + 12)
        cy = y + 30
        for j, text in enumerate(items):
            num = col_i * 14 + j + 1
            draw_text(str(num), cx, cy, 9, INK, 1.2, font="sans")
            size = fit_size(text, 8.5, col_w - 18, font="serif-reg",
                            weight=W_BODY)
            draw_text(text, cx + 16, cy, size, INK_SOFT, W_BODY,
                      font="serif-reg")
            cy += 14.5


def draw_datecheck_panel(x, y, w, h):
    fill_rect(x, y, w, h, CARD)
    hline(x, y, w, INK, 2)
    hline(x, y + h - 2, w, INK, 2)
    vline(x, y, h, INK, 2)
    vline(x + w - 2, y, h, INK, 2)
    fill_rect(x + 2, y + 2, w - 4, 28, YELLOW)
    draw_text("DATE CHECK", x + 10, y + 7, 14, BLACK, 1.6, font="sans")
    items = [
        "ICJ Myanmar ruling (Thu, 19 Nov) \u2013 not included",
        "Shenzhen Declaration (Thu, 19 Nov) \u2013 not included",
        "GTA VI launch (Thu, 19 Nov) \u2013 not included",
        "Final COP31 text not agreed on Friday",
    ]
    cy = y + 38
    for item in items:
        check_mark(x + 10, cy + 1, 11, BLACK)
        hh = draw_block(item, x + 28, cy, 10, BLACK, W_BODY, w - 38, 14,
                        font="serif-reg")
        cy += hh + 7
    box_h = 54
    fill_rect(x + 2, y + h - box_h, w - 4, box_h - 2, YELLOW)
    draw_block("All stories here happened, or were first reported, on "
               "Friday 20 November 2026.",
               x + 10, y + h - box_h + 6, 10.5, BLACK, W_BODY, w - 20, 14.5,
               font="serif-reg")


def draw_bottom_band():
    draw_map_panel(MX, BAND_Y, 330, BAND_H)
    draw_index_panel(377, BAND_Y, 370, BAND_H)
    draw_datecheck_panel(758, BAND_Y, 230, BAND_H)


def draw_footer():
    hline(MX, 1004, CW, INK, 1)
    draw_text("Sources: Reuters | AP | BBC | The Guardian | AFP | Anadolu "
              "| DW | UN News | ABC | and more.",
              MX, 1012, 9.5, INK_SOFT, W_LABEL, font="sans-reg")
    draw_text("A snapshot of the world on Friday, 20 November 2026.",
              W - MX, 1012, 9.5, INK_SOFT, W_LABEL, align="right",
              font="sans-reg")


# Page assembly and entry point
# ---------------------------------------------------------------------------
def draw_page():
    _fill_paper()
    draw_top_line()
    draw_date()
    draw_subhead()
    draw_numbers_strip()
    draw_region_bar()
    draw_lead_section()
    draw_medium_section()
    draw_small_section()
    draw_bottom_band()
    draw_footer()


def main():
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR", "out")
    os.makedirs(outdir, exist_ok=True)
    draw_page()
    write_png(os.path.join(outdir, "entry.png"))


if __name__ == "__main__":
    main()
